<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import {Head,useForm} from '@inertiajs/vue3';defineProps<{members:any[]}>();const save=(m:any)=>{if((m.role==='owner'||m.status==='active')&&!confirm(`Save changes for ${m.user.name}? Final-owner protection will be enforced.`))return;useForm({role:m.role,status:m.status}).patch(route('members.update',m.id));};</script>
<template><Head title="Members"/><AuthenticatedLayout><h1 class="h2">Tenant members</h1><p class="text-secondary">Invitations are deferred; current members must already have user accounts.</p><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Member</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td>{{m.user.name}}<small class="d-block text-secondary">{{m.user.email}}</small></td><td><select v-model="m.role" class="form-select form-select-sm"><option>owner</option><option>administrator</option><option>teacher</option><option>parent</option><option>tutor</option><option>student</option></select></td><td><select v-model="m.status" class="form-select form-select-sm"><option>active</option><option>inactive</option></select></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" @click="save(m)">Save</button></td></tr></tbody></table></div></div></AuthenticatedLayout></template>
